/* Two hobby servos on OC1A (D9) and OC1B (D10): 50 Hz, 0.5 us steps. */
#include <avr/io.h>
#include <stdint.h>

void servos_init(void)
{
    DDRB  |= (1u << PB1) | (1u << PB2);         /* OC1A and OC1B as outputs */
    ICR1   = 39999u;                            /* 16 MHz / 8 / 40000 = 50 Hz */
    OCR1A  = 2999u;                             /* 1500 us: centre */
    OCR1B  = 2999u;
    TCCR1A = (1u << COM1A1) | (1u << COM1B1) | (1u << WGM11);
    TCCR1B = (1u << WGM13) | (1u << WGM12) | (1u << CS11);  /* mode 14, /8 */
}

void servo_us(uint8_t canal, uint16_t us)       /* pulse width in us */
{
    if (us < 500u)  us = 500u;                  /* never outside the */
    if (us > 2500u) us = 2500u;                 /* mechanical range  */
    if (canal == 0) OCR1A = 2u * us - 1u;       /* high for OCR1x + 1 */
    else            OCR1B = 2u * us - 1u;       /* ticks; buffered     */
}

/* x4 quadrature decoding by table: index = previous AB, current AB. */
#include <stdint.h>

static const int8_t paso_ab[16] = {
     0, +1, -1,  0,      /* from 00 to 00, 01, 10, 11 */
    -1,  0,  0, +1,      /* from 01 */
    +1,  0,  0, -1,      /* from 10 */
     0, -1, +1,  0,      /* from 11 */
};

volatile int32_t posicion;     /* counts, updated only here */
volatile uint16_t errores;     /* both bits changed: a lost edge */
static uint8_t ab_ant;

void encoder_actualiza(uint8_t ab)          /* ab = (A << 1) | B */
{
    uint8_t i = (uint8_t)((ab_ant << 2) | ab);
    if (i == 0x3 || i == 0x6 || i == 0x9 || i == 0xC)
        errores++;                          /* 00<->11 or 01<->10 */
    posicion += paso_ab[i];
    ab_ant = ab;
}

/* Odometry of a differential robot, one step from the encoder counts. */
#include <math.h>
#include <stdint.h>

#define M_POR_CUENTA (3.14159265f * 0.065f / 1320.0f)   /* wheel 65 mm */
#define VIA          0.150f                             /* track, m   */

typedef struct { float x, y, th; } pose_t;

void odometria(pose_t *p, int16_t cuentas_d, int16_t cuentas_i)
{
    float dd  = cuentas_d * M_POR_CUENTA;     /* right wheel, m */
    float di  = cuentas_i * M_POR_CUENTA;     /* left wheel, m  */
    float ds  = 0.5f * (dd + di);
    float dth = (dd - di) / VIA;
    p->x  += ds * cosf(p->th + 0.5f * dth);   /* mid-step heading */
    p->y  += ds * sinf(p->th + 0.5f * dth);
    p->th += dth;
}

/* Stepper ramp (D. Austin, 2005) in the Timer1 compare ISR, CTC mode.
   c = timer counts (2 MHz) to the next step, in Q8 fixed point. */
#include <avr/io.h>
#include <avr/interrupt.h>
#include <stdint.h>

#define C0_Q8   (23900ul << 8)        /* first interval: 11.95 ms */
#define CMIN_Q8 (625ul << 8)          /* cruise: 3200 microsteps/s */

static uint32_t c_q8;
static uint16_t n;                    /* steps of the ramp so far */
static volatile uint16_t restantes;

ISR(TIMER1_COMPA_vect)
{
    if (restantes == 0) { TIMSK1 = 0; return; }     /* move done */
    PORTD |= (1u << PD4);             /* STEP high (>= 1.9 us) */
    restantes--;
    if (restantes < n) {              /* brake over as many steps */
        c_q8 += (2u * c_q8) / (4u * n - 1u);        /* as it took */
        n--;
    } else if (c_q8 > CMIN_Q8) {      /* accelerate */
        n++;
        c_q8 -= (2u * c_q8) / (4u * n + 1u);
        if (c_q8 < CMIN_Q8) c_q8 = CMIN_Q8;
    }
    OCR1A = (uint16_t)(c_q8 >> 8);
    PORTD &= ~(1u << PD4);            /* STEP low */
}

void mueve(uint16_t pasos)            /* DIR already set on PD5 */
{
    c_q8 = C0_Q8; n = 0; restantes = pasos;
    OCR1A = (uint16_t)(C0_Q8 >> 8);
    TCNT1 = 0;
    TCCR1A = 0;
    TCCR1B = (1u << WGM12) | (1u << CS11);          /* CTC, 16 MHz / 8 */
    TIFR1 = (1u << OCF1A);
    TIMSK1 = (1u << OCIE1A);
}

/* Inverse kinematics of the arm: base t1, shoulder t2, elbow t3 (rad). */
#include <math.h>
#include <stdbool.h>

#define L1 0.120f                     /* upper arm, m */
#define L2 0.100f                     /* forearm, m   */

bool cinematica_inversa(float x, float y, float z, float t[3])
{
    float r = sqrtf(x * x + y * y);
    float D = (r * r + z * z - L1 * L1 - L2 * L2) / (2.0f * L1 * L2);
    if (D < -1.0f || D > 1.0f)
        return false;                 /* point out of reach */
    t[0] = atan2f(y, x);
    t[2] = -acosf(D);                 /* elbow up */
    t[1] = atan2f(z, r) - atan2f(L2 * sinf(t[2]), L1 + L2 * cosf(t[2]));
    return true;
}
